using System;using System.IO;using System.Text;using System.Text.RegularExpressions;using System.Security.Cryptography;using System.Web.Script.Serialization;using System.Diagnostics;using System.Runtime.InteropServices;using System.IO.Pipes;using System.Threading.Tasks;using System.Security.AccessControl;using System.Security.Principal;
public sealed class ServiceRelease {public string Tag,Url,Sha256;public long Size;}
public sealed class ServiceDocument {public int Schema;public string State,Announcement,RequiredVersion,PublishedUtc;public ServiceRelease Release;}
public sealed class SignedServicePolicy {public string Payload,Signature;}
public sealed class AuthorizedSession {public int ManagerPid;public long ManagerStartTicks;public string Envelope,Pipe;}
public static class ServicePolicy {
 public const string PublicKey="<RSAKeyValue><Modulus></Modulus><Exponent>AQAB</Exponent></RSAKeyValue>";
 public const string Address="https://raw.githubusercontent.com/w-rakeeb/dual-steam/main/service-policy.json";
 public static Version Version(string value){System.Version v;if(!Regex.IsMatch(value??"",@"^[0-9]+\.[0-9]+\.[0-9]+$")||!System.Version.TryParse(value,out v))throw new IOException("Invalid service release version.");return v;}
 public static ServiceDocument Verify(string envelope){return Verify(envelope,PublicKey);}
 public static ServiceDocument Verify(string envelope,string key){
  if(String.IsNullOrEmpty(envelope)||envelope.Length>65536)throw new IOException("Invalid service announcement.");var json=new JavaScriptSerializer{MaxJsonLength=65536};var signed=json.Deserialize<SignedServicePolicy>(envelope);if(signed==null||String.IsNullOrEmpty(signed.Payload)||String.IsNullOrEmpty(signed.Signature))throw new IOException("Unsigned service announcement rejected.");byte[] payload,signature;try{payload=Convert.FromBase64String(signed.Payload);signature=Convert.FromBase64String(signed.Signature);}catch(FormatException){throw new IOException("Invalid service signature format.");}
  if(payload.Length>32768||signature.Length>512)throw new IOException("Service announcement is too large.");using(var rsa=new RSACryptoServiceProvider()){rsa.PersistKeyInCsp=false;rsa.FromXmlString(key);if(!rsa.VerifyData(payload,CryptoConfig.MapNameToOID("SHA256"),signature))throw new IOException("Service announcement signature could not be verified.");}
  var policy=json.Deserialize<ServiceDocument>(new UTF8Encoding(false,true).GetString(payload));if(policy==null||policy.Schema!=1||!Regex.IsMatch(policy.State??"",@"^(active|paused|shutdown)$")||(policy.Announcement??"").Length>2000)throw new IOException("Unsupported service announcement.");Version(policy.RequiredVersion);DateTime issued;if(!DateTime.TryParse(policy.PublishedUtc,System.Globalization.CultureInfo.InvariantCulture,System.Globalization.DateTimeStyles.RoundtripKind,out issued))throw new IOException("Invalid service announcement date.");
  if(policy.Release!=null){var r=policy.Release;Uri uri;if(r.Tag!="v"+policy.RequiredVersion||!Uri.TryCreate(r.Url,UriKind.Absolute,out uri)||uri.Scheme!="https"||uri.Host!="github.com"||uri.AbsolutePath!="/w-rakeeb/dual-steam/releases/download/"+r.Tag+"/Dual-Steam-Windows.zip"||!String.IsNullOrEmpty(uri.Query)||!String.IsNullOrEmpty(uri.Fragment)||!String.IsNullOrEmpty(uri.UserInfo)||!Regex.IsMatch(r.Sha256??"","^[a-f0-9]{64}$")||r.Size<=0||r.Size>50*1024*1024)throw new IOException("Invalid signed update location or checksum.");}
  return policy;
 }
 public static string Decision(ServiceDocument policy,System.Version installed){if(policy.State!="active")return policy.State;if(installed<Version(policy.RequiredVersion))return "update";return "allowed";}
}
public static class RuntimeAuthorization {
 [DllImport("kernel32",SetLastError=true)]static extern IntPtr OpenProcess(uint access,bool inherit,int pid);[DllImport("kernel32")]static extern bool CloseHandle(IntPtr handle);[DllImport("kernel32",CharSet=CharSet.Unicode)]static extern bool QueryFullProcessImageName(IntPtr handle,uint flags,StringBuilder name,ref uint count);
 static string SessionFile(string home){return Path.Combine(home,@"Data\Authorization\session.json");}
 public static void BeginStartup(string home){ManagerSessionHost.Revoke();string file=SessionFile(home);SettingsTransfer.NoLinks(file);if(File.Exists(file))File.Delete(file);}
 public static void Authorize(string home,string envelope){var version=System.Reflection.AssemblyName.GetAssemblyName(Path.Combine(home,"Dual Steam.exe")).Version;var policy=ServicePolicy.Verify(envelope);if(ServicePolicy.Decision(policy,version)!="allowed")throw new IOException("This startup is not authorized by the service announcement.");string file=SessionFile(home);SettingsTransfer.NoLinks(file);Directory.CreateDirectory(Path.GetDirectoryName(file));using(var process=Process.GetCurrentProcess()){var session=new AuthorizedSession{ManagerPid=process.Id,ManagerStartTicks=process.StartTime.ToUniversalTime().Ticks,Envelope=envelope,Pipe=ManagerSessionHost.Authorize()};SettingsTransfer.WriteAtomic(file,Encoding.UTF8.GetBytes(new JavaScriptSerializer().Serialize(session)));}}
 public static bool Valid(string home){try{Require(home);return true;}catch{return false;}}
 public static void Require(string home){
  string file=SessionFile(home);SettingsTransfer.NoLinks(file);if(!File.Exists(file)||new FileInfo(file).Length>100000)throw new IOException("Open Dual Steam and complete its startup service check first.");var session=new JavaScriptSerializer{MaxJsonLength=100000}.Deserialize<AuthorizedSession>(File.ReadAllText(file));if(session==null||!Regex.IsMatch(session.Pipe??"",@"^DualSteamSession_[a-f0-9]{32}$"))throw new IOException("Invalid startup session.");var policy=ServicePolicy.Verify(session.Envelope);
  using(var manager=Process.GetProcessById(session.ManagerPid)){if(manager.StartTime.ToUniversalTime().Ticks!=session.ManagerStartTicks)throw new IOException("The authorized session has ended.");IntPtr handle=OpenProcess(0x1000,false,manager.Id);try{var name=new StringBuilder(2048);uint length=(uint)name.Capacity;if(handle==IntPtr.Zero||!QueryFullProcessImageName(handle,0,name,ref length)||!name.ToString().Equals(Path.Combine(home,"Dual Steam.exe"),StringComparison.OrdinalIgnoreCase))throw new IOException("The authorized manager is not running.");}finally{if(handle!=IntPtr.Zero)CloseHandle(handle);}}
  if(ServicePolicy.Decision(policy,System.Reflection.AssemblyName.GetAssemblyName(Path.Combine(home,"Dual Steam.exe")).Version)!="allowed")throw new IOException("This session requires an update or the service is unavailable.");ManagerSessionHost.Confirm(session);
 }
}
